// HasTransitionCase applies the HasEdge predicate on the "transition_case" edge.
func HasTransitionCase() predicate.AccountHandlingTask {
	return predicate.AccountHandlingTask(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TransitionCaseTable, TransitionCaseColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTransitionCaseWith applies the HasEdge predicate on the "transition_case" edge with a given conditions (other predicates).
